export interface ToolDef {
  id: string;
  title: string;
  khmerTitle?: string;
  /** ISO date for homepage daily-addition grouping; omit when provenance is unknown. */
  addedOn?: string;
  category: Category;
  keywords: string[];
  localProject?: { author: string; repository: string; license: string; relationship?: "adapted" | "integrated" | "inspired" };
  /**
   * Component file under components/tools/ (e.g. "dev/json-formatter"). The registry stays
   * free of React components so server code (layout, SEO, sitemap, tool pages) can import it
   * without pulling every tool into every page; lib/tool-components.tsx resolves it lazily.
   */
  module: string;
  /** Props passed to a shared engine component (the generated unit/temperature pairs). */
  props?: Record<string, string>;
}

